  padding: 1rem 1.5rem;
}

/* 图标颜色 */
.ti { color: inherit; }
.meta-item .ti { color: var(--route-blue); }
.food-card .ti { color: var(--food-amber); }
.stay-card .ti { color: var(--stay-olive); }
.tips-box .ti { color: var(--alert-rust); }
```

---

## 装饰元素样式

```css
/* 指南针 */
.compass-rose {
  display: flex;
  justify-content: center;
  margin: 2rem 0;
  color: var(--text-tertiary);
}

/* 分隔线 */
.divider {
  display: flex;
  justify-content: center;
  margin: 2.5rem 0;
  color: var(--border-warm);
