/* 封面双线边框 */
.cover {
  position: relative;
  padding: 4rem 3rem;
  page-break-after: always;
}
.cover::before {
  content: "";
  position: absolute;
  top: 1.5rem; left: 1.5rem; right: 1.5rem; bottom: 1.5rem;
  border: 1.5px solid var(--terracotta);
  border-radius: 4px;
  opacity: 0.4;
}
.cover::after {
  content: "";
  position: absolute;
  top: 2rem; left: 2rem; right: 2rem; bottom: 2rem;
  border: 0.5px solid var(--terracotta);
  border-radius: 2px;
  opacity: 0.25;
}

/* 卡片角标装饰 */
.stop-card,
.food-card,
.stay-card {
  position: relative;
  background: var(--ivory);
  border-radius: 10px;
  padding: 1.5rem;
  margin-bottom: 2rem;
